37	template <pipe_t srcPipe, pipe_t dstPipe>
38	AICORE inline void SetFlag(uint32_t id)
39	{
40	    set_flag(srcPipe, dstPipe, static_cast<event_t>(id));
41	}
42	template <pipe_t srcPipe, pipe_t dstPipe>
43	AICORE inline void WaitFlag(uint32_t id)
44	{
45	    wait_flag(srcPipe, dstPipe, static_cast<event_t>(id));
46	}
47	
48	template <
49	    typename T, typename U, typename S, int m, int k, int n, uint32_t singleCoreM, uint32_t singleCoreK,
50	    uint32_t singleCoreN>
51	AICORE inline void InitGMOffsets(
52	    __gm__ U*& currentSrc0, __gm__ S*& currentSrc1, __gm__ T*& currentDst, __gm__ T* out, __gm__ U* src0,
53	    __gm__ S* src1)
54	{
55	    // Work partition (SPMD-style):
56	    // - Each core owns a contiguous C tile of shape [singleCoreM, singleCoreN].
57	    // - It reads the corresponding A panel [singleCoreM, K] and B panel [K, singleCoreN].
58	    constexpr uint32_t mIter = m / singleCoreM;
59	    uint32_t mIterIdx = get_block_idx() % mIter; // get current launch core idx
60	    uint32_t nIterIdx = get_block_idx() / mIter;
61	    uint64_t gmOffsetA = mIterIdx * singleCoreM * k;
62	    uint64_t gmOffsetB = nIterIdx * k * singleCoreN;
63	    uint64_t gmOffsetC = mIterIdx * singleCoreM * n + nIterIdx * singleCoreN;
64	    currentSrc0 = src0 + gmOffsetA;
65	    currentSrc1 = src1 + gmOffsetB;
66	    currentDst = out + gmOffsetC;
67	}
68	
69	template <
70	    typename T, typename U, typename S, int m, int k, int n, uint32_t baseM, uint32_t baseK, uint32_t baseN,
71	    uint32_t stepKa, uint32_t stepKb, uint32_t singleCoreK, typename TileMatA, typename TileMatB, typename LeftTile,
72	    typename RightTile, typename ResTile>
73	AICORE inline void ProcessKIteration(
74	    uint32_t kIter, uint32_t i, uint32_t j, __gm__ U* currentSrc0, __gm__ S* currentSrc1, TileMatA aMatTile[BUFFER_NUM],
75	    TileMatB bMatTile[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM], ResTile& cTile,
76	    uint8_t& mte2DBFlag, uint8_t& mte1DBFlag)
77	{
78	    // A panel staged by each TLOAD (GM->L1) when kModstepKa == 0: [baseM, baseK * stepKa]
79	    using NDValidShapeA = TileShape2D<U, baseM, baseK * stepKa, Layout::ND>;
80	    using NDsingleCoreShapeA = BaseShape2D<U, m, k, Layout::ND>;
81	    using GlobalDataSrcA = GlobalTensor<U, NDValidShapeA, NDsingleCoreShapeA, Layout::ND>;
82	
83	    // B panel staged by each TLOAD (GM->L1) when kModstepKa == 0: [baseK * stepKb, baseN]
84	    using NDValidShapeB = TileShape2D<U, baseK * stepKb, baseN, Layout::DN>;
85	    using NDsingleCoreShapeB = BaseShape2D<U, k, n, Layout::DN>;
86	    using GlobalDataSrcB = GlobalTensor<U, NDValidShapeB, NDsingleCoreShapeB, Layout::DN>;
87	
88	    const uint32_t kModstepKa = kIter % stepKa;
89	
90	    // TLOAD stage:
91	    // - Every stepKa iterations, load a larger [baseM, baseK * stepKa] panel into L1 and then slice it with TEXTRACT.
92	    // - Double buffering is driven by mte2DBFlag.
93	    if (kModstepKa == 0) {
94	        GlobalDataSrcA gmA(currentSrc0 + i * singleCoreK * baseM + kIter * baseK);
95	        GlobalDataSrcB gmB(currentSrc1 + j * singleCoreK * baseN + kIter * baseK);
96	
97	        // Wait until TEXTRACT is done with this L1 buffer before reusing it.
98	        WaitFlag<PIPE_MTE1, PIPE_MTE2>(mte2DBFlag);
99	        TLOAD(aMatTile[mte2DBFlag], gmA);
100	        SetFlag<PIPE_MTE2, PIPE_MTE1>(0);
101	        TLOAD(bMatTile[mte2DBFlag], gmB);
102	        SetFlag<PIPE_MTE2, PIPE_MTE1>(1);
103	        mte2DBFlag = (mte2DBFlag == 0) ? 1 : 0;
104	    }
105	
106	    const uint32_t currMte2Idx = (mte2DBFlag == 0) ? 1 : 0; // mte2DBFlag reversed
107	    // Wait until TMATMUL is done with the current L0A/L0B buffer before overwriting it via TEXTRACT.
108	    WaitFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
109	
110	    // TEXTRACT stage: slice the loaded L1 panel into the baseK chunk we need this iteration.
111	    if (kModstepKa == 0)
112	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(0);
113	    TEXTRACT(aTile[mte1DBFlag], aMatTile[currMte2Idx], 0, kModstepKa * baseK);
114	
115	    if (kModstepKa == 0)
116	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(1);
117	    TEXTRACT(bTile[mte1DBFlag], bMatTile[currMte2Idx], (kIter % stepKb) * baseK, 0);
118	
119	    if ((kIter + 1) % stepKa == 0) {
120	        // Allow the next TLOAD to reuse this L1 slot.
121	        SetFlag<PIPE_MTE1, PIPE_MTE2>(currMte2Idx);
122	    }
123	
124	    // TMATMUL stage: compute (or accumulate) into cTile.
125	    SetFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
126	    WaitFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
127	    MatmulAcc(cTile, aTile[mte1DBFlag], bTile[mte1DBFlag], kIter);
128	    // Signal that TMATMUL is done, so the next iteration may TEXTRACT into the other ping-pong slot.
129	    SetFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
130	    mte1DBFlag = (mte1DBFlag == 0) ? 1 : 0;
131	}
